using System.IO;
using System.Text.Json;
using System.Windows;
namespace AnoWowItemEditor;
public partial class MainWindow
{
    private async Task VerifySetReview(CatalogResult catalog)
    {
        static void Assert(bool value,string message){if(!value)throw new InvalidOperationException(message);}
        var lookup=catalog.Items.ToDictionary(i=>i.Id);var head=lookup[22418];var chest=lookup[22416];var two=lookup.Values.First(i=>i.Slot==17);var off=lookup.Values.First(i=>i.Slot==14);var ring=lookup.Values.First(i=>i.Slot==11);var boots=lookup[22420];var hero=new CharacterInfo(999999,"Set preview fixture",60,1,false,0);
        OwnedItem Owned(CatalogItem item,int slot,ulong guid,bool equipped=true)=>new(guid,item.Id,1,0,slot,equipped?"Equipped":"Backpack",100,"","",0,0,equipped);
        var before=new CharacterSnapshot(hero,[Owned(head,0,1),Owned(off,16,2),Owned(two,15,3),Owned(ring,10,4),Owned(ring,11,5),Owned(boots,7,6),Owned(chest,23,7,false)]);string unchanged=JsonSerializer.Serialize(before);var result=SetDesignReview.Equip(before,[head,chest,two],lookup,60);Assert(result.Slots.Count==3&&result.After.Items.Where(i=>i.Equipped&&i.Slot is 15 or 16).Count()==1,"Whole-set preview handles both hand slots for a two-handed weapon");Assert(result.After.Items.Any(i=>i.Guid==6)&&result.After.Items.Any(i=>i.Guid==7),"Whole-set preview preserves untouched slots and inventory");Assert(result.After.Items.Where(i=>i.Location=="Set preview").Select(i=>i.Guid).Distinct().Count()==3,"Synthetic set items have distinct instance identities");Assert(JsonSerializer.Serialize(before)==unchanged,"Full-set simulation leaves the saved character snapshot unchanged");
        var candidate=new CatalogItem(new(ring.Fields,StringComparer.OrdinalIgnoreCase){["ID"]="2000000002",["MaxCount"]="0",["AllowableClass"]="-1",["RequiredLevel"]="1"});lookup[candidate.Id]=candidate;var finger=SetDesignReview.Equip(before,[candidate],lookup,60,new Dictionary<int,int>{{candidate.Id,11}});Assert(finger.After.Items.Any(i=>i.Guid==4)&&!finger.After.Items.Any(i=>i.Guid==5),"Single set ring can replace the second finger independently");var conflicting=SetDesignReview.Equip(before,[two,off],lookup,60);Assert(!conflicting.Allowed&&conflicting.Problems.Any(p=>p.Contains("no free compatible")),"Conflicting set pieces are explicitly reported");
        var restricted=new CatalogItem(new(head.Fields,StringComparer.OrdinalIgnoreCase){["AllowableClass"]="64",["RequiredLevel"]="60",["RequiredSkill"]="123",["RequiredSkillRank"]="200"});var blocked=SetDesignReview.Equip(before,[restricted],lookup,10);Assert(!blocked.Allowed&&blocked.Problems.Any(p=>p.Contains("class"))&&blocked.Problems.Any(p=>p.Contains("requires level"))&&blocked.Problems.Any(p=>p.Contains("skill")),"Character set preview identifies class, level and skill failures");
        var empty=before with{Items=[]};var pure=SetDesignReview.Equip(empty,[head,chest],lookup,60);var totals=GearDesign.Compare(empty,pure.After,lookup,catalog.Tooltips,60);int strength=new[]{head,chest}.Sum(item=>catalog.Tooltips.Calculations.Evaluate(item,60).Stats.Where(p=>item.Number("StatModifierBonusStat"+p.Key)==4).Sum(p=>p.Value));if(strength>0)Assert(totals.Single(t=>t.Name=="Strength").After==strength.ToString(),"Full-set totals add actual calculated base stats");var unknown=before with{Items=before.Items.Select(i=>i.Guid==1?i with{BonusLists="999999"}:i).ToList()};Assert(GearDesign.Compare(unknown,result.After,lookup,catalog.Tooltips,60).Any(m=>m.Change=="[unresolved]"),"Unsupported owned modifiers remain unresolved in set deltas");
        var set=catalog.Tooltips.Sets[523];var pieces=set.Members.Where(lookup.ContainsKey).Select(id=>lookup[id]).ToArray();var same=SetDesignReview.Balance(catalog,set,set,pieces,60);Assert(same.Metrics.All(m=>m.Change=="0"),"Comparing the same set gives zero deltas");var subset=pieces.Where(i=>i.Slot!=11).ToArray();var common=SetDesignReview.Balance(catalog,set,set,subset,60);Assert(common.Metrics.All(m=>m.Change=="0")&&common.Findings.Any(f=>f.Contains("Reference-only slots")),"Common-slot comparison excludes missing ring rather than inflating differences");
        var over=new CatalogItem(new(chest.Fields,StringComparer.OrdinalIgnoreCase){["ID"]="2000000003",["StatModifierBonusStat1"]="4",["StatPercentEditor1"]="100000000"});var withOutlier=catalog with{Items=catalog.Items.Append(over).ToList()};var outlier=SetDesignReview.Balance(withOutlier,new(9999,"Outlier fixture",[over.Id],[]),set,[over],60);Assert(outlier.Findings.Any(f=>f.Contains("unusually high",StringComparison.OrdinalIgnoreCase)),"Set balance flags an extreme allocation against actual exact peers");
        var window=new SetAnalysisWindow(catalog,523){Owner=this};window.Show();await window.SetVerificationCharacter(before);Assert(window.PreviewResult is not null&&window.BalanceResult is not null,"Set review window renders both reports");await RenderEditorWindow(window,"full-set-character-preview");window.SelectVerificationTab(1);await RenderEditorWindow(window,"set-balance-review-preview");window.Close();
        await File.WriteAllTextAsync("artifacts/set-review-verification.json",JsonSerializer.Serialize(new{checks="Full-set placement; distinct synthetic instances; both-hand replacement; ring-slot choice; untouched inventory; class/level/skill checks; conflicts; base-stat totals; unresolved instance values; zero self-comparison; fair common-slot comparison; allocation outliers; read-only UI; no game writes"},new JsonSerializerOptions{WriteIndented=true}));
    }
}
